'use strict';
const V261={
 states:{WORKING:'备货作业中',PENDING:'待审核',RECTIFY:'已驳回/待整改',PREPARED:'已备货',PARTIAL:'部分装车',FULFILLED:'全部出库',CANCELLED:'已取消'},
 sampleStates:{NOT_REQUIRED:'无需取样',WAITING:'待取样',IN_PROGRESS:'取样中',RETURNED:'已返回/已重新打包',WEIGHED:'已完成检斤'},drafts:new Map(),
 actionNames:{CREATE_ITEM:'加入备货Lot',WEIGH:'检斤重量录入/修订','SAMPLE-STAGE':'取样进度更新','SAMPLE-MARK':'取样标记调整',SUBMIT:'提交备货审核',REJECT:'驳回待整改',APPROVE:'审核通过',CANCEL:'取消Lot',REOPEN:'主管授权更正'},
 historySummary(d){if(!d)return '无先前记录';const parts=[];if(d.sample_stage)parts.push(this.sampleStates[d.sample_stage]||d.sample_stage);if(typeof d.sample_required==='boolean')parts.push(d.sample_required?'需要取样':'无需取样');if(typeof d.final_weighed==='boolean')parts.push(d.final_weighed?'已完成检斤':'待检斤');if(d.gross_weight!==undefined&&d.gross_weight!==null)parts.push('毛重 '+V26.weight(d.gross_weight)+' t');if(d.net_weight!==undefined&&d.net_weight!==null)parts.push('净重 '+V26.weight(d.net_weight)+' t');if(d.workflow_state)parts.push(this.states[d.workflow_state]||d.workflow_state);return parts.join(' · ')||'已记录';},
 async allocations(){const [plans,lots]=await Promise.all([API.request('/plans'),API.request('/allocations')]);Business.open('备货管理',`<div class="business-toolbar">${Business.can('allocation:write')?'<a class="button primary" href="/preparation/new">新建备货Lot</a>':''}${Business.can('plan:write')?'<button id="v261-plan-new" class="button secondary">新建销售计划</button>':''}<a class="button secondary" href="/preparation/history-sampling">历史取样记录</a></div><p>创建Lot立即锁定 → 分阶段取样与检斤 → 全部完成后提交主管审核。规划货位在主管确认归位后成为正式货位。</p><h3>销售计划</h3><div class="business-table"><table><thead><tr><th>计划</th><th>客户 / 合同</th><th>目标净重(t)</th><th>状态</th><th></th></tr></thead><tbody>${plans.items.map(p=>`<tr><td>${esc(p.code)}</td><td>${esc(p.customer_name)} · ${esc(p.contract_no||'未关联')}</td><td>${esc(Tonnes.format(p.target_weight))}</td><td>${p.status==='OPEN'?'开放':'关闭'}</td><td>${Business.can('plan:write')?`<button data-v261-plan="${p.id}">编辑</button>`:''}</td></tr>`).join('')}</tbody></table></div><h3>备货Lot</h3><div class="business-table"><table><thead><tr><th>Lot / 单号</th><th>客户</th><th>计划</th><th>状态</th><th></th></tr></thead><tbody>${lots.items.map(a=>`<tr><td>${esc(a.lot_no||a.code)}</td><td>${esc(a.customer_name)}</td><td>${esc(a.plan_code)}</td><td>${esc(a.workflow_version==='2.6.1'?this.states[a.workflow_state]:(V26.states[a.workflow_state]||{DRAFT:'历史草稿',LOCKED:'历史锁定',RELEASED:'历史释放',FULFILLED:'历史已出库'}[a.status]))}</td><td><a href="/preparation/${a.id}">详情 / 作业</a></td></tr>`).join('')}</tbody></table></div>`);if($('v261-plan-new'))$('v261-plan-new').onclick=()=>Business.planForm();for(const b of document.querySelectorAll('[data-v261-plan]'))b.onclick=()=>Business.planForm(plans.items.find(p=>p.id===b.dataset.v261Plan));},
 async create(){const [ps,m,map,contracts,availability]=await Promise.all([API.request('/plans'),Business.load(),API.request('/stock-map'),API.request('/contracts'),API.request('/v262/locations')]);const plans=ps.items.filter(p=>p.status==='OPEN'&&(!p.contract_id||contracts.items.some(c=>c.id===p.contract_id&&c.validity==='VALID'))),chosen=new Map();let rows=[],scope=[],page=1,total=0,sequence=0;
 Business.open('新建备货Lot',`<form id="v261-create" class="user-form"><div class="form-grid"><label>销售计划<select id="v261-plan" required><option value="">请选择有效销售计划</option>${plans.map(p=>`<option value="${p.id}">${esc(p.code+' · '+p.customer_name)}</option>`).join('')}</select></label><label>规划堆存货位<select id="v261-planned" required><option value="">请选择统一规划货位</option></select></label></div><p id="v261-plan-info">客户及合同由销售计划自动带出，不可手工改客户。</p><p>规划货位并非已确认实际货位；无需逐捆填写位置。创建前勾选及取样标记不锁定。</p><div class="business-toolbar"><label>捆包编号搜索<input id="v261-search" type="search" maxlength="512"></label><button id="v261-search-btn" type="button" class="button secondary">搜索</button><button id="v261-clear" type="button" class="button secondary">清空全部已选</button></div><p id="v261-range">表头全选作用于当前筛选结果的所有页，最多500捆；搜索和翻页保留其他选择。</p><div id="v261-picker"></div><div class="business-toolbar"><button id="v261-prev" type="button">上一页</button><span id="v261-page"></span><button id="v261-next" type="button">下一页</button></div><div id="v261-selection"></div><p id="v261-totals" aria-live="polite"></p><p id="v261-error" class="error" role="alert"></p><button type="submit" class="button primary">创建Lot</button></form><dialog id="v261-lot-dialog"><form id="v261-lot-form" class="user-form"><h2>Lot No.</h2><label>Lot No.<input id="v261-lot-no" required pattern="RMM-CU-[0-9]{4}-(0[1-9]|[1-9][0-9])" placeholder="RMM-CU-2026-01"></label><p>最终确认成功才锁定捆包，创建时无需检斤重量。</p><p id="v261-modal-error" class="error" role="alert"></p><div class="business-toolbar"><button id="v261-modal-cancel" type="button">取消</button><button class="button primary">确认创建并开始备货</button></div></form></dialog>`);
 const header=()=>{const box=$('v261-all');if(!box)return;const n=scope.filter(r=>chosen.has(r.uuid)).length;box.checked=scope.length>0&&n===scope.length;box.indeterminate=n>0&&n<scope.length;box.disabled=!scope.length||total>500;};
 const summary=()=>{$('v261-totals').textContent=`已选择 ${chosen.size} 捆 · 取样 ${[...chosen.values()].filter(r=>r.sample_required).length} 捆 · 已检斤 0 捆 · 已知毛重 0.0000 t / 已知净重 0.0000 t（本Lot尚未检斤）`;$('v261-selection').textContent='已选：'+[...chosen.values()].map(r=>r.id+(r.sample_required?'（取样）':'')).join('、');header();};
 const draw=()=>{$('v261-picker').innerHTML='<div class="business-table"><table><thead><tr><th><label><input id="v261-all" type="checkbox" aria-label="全选或取消当前筛选结果">全选筛选结果</label></th><th>捆包编号</th><th>生产批次</th><th>取样</th><th>取样状态</th><th>毛重(t)</th><th>净重(t)</th></tr></thead><tbody>'+rows.map(r=>`<tr><td><input type="checkbox" data-v261-pick="${r.uuid}" aria-label="备货选择 ${esc(r.id)}" ${chosen.has(r.uuid)?'checked':''}></td><td>${esc(r.id)}</td><td>${esc(r.batch)}</td><td><input type="checkbox" data-v261-sample="${r.uuid}" aria-label="取样选择 ${esc(r.id)}" ${chosen.get(r.uuid)?.sample_required?'checked':''} ${chosen.has(r.uuid)?'':'disabled'}></td><td>${chosen.get(r.uuid)?.sample_required?'待取样':'无需取样'}</td><td>待检斤</td><td>待检斤</td></tr>`).join('')+'</tbody></table></div>';
 for(const cb of document.querySelectorAll('[data-v261-pick]'))cb.onchange=()=>{const row=rows.find(r=>r.uuid===cb.dataset.v261Pick);if(cb.checked)chosen.set(row.uuid,{...row,sample_required:false});else chosen.delete(row.uuid);draw();summary();};
 for(const cb of document.querySelectorAll('[data-v261-sample]'))cb.onchange=()=>{const row=chosen.get(cb.dataset.v261Sample);if(row)row.sample_required=cb.checked;draw();summary();};
 $('v261-all').onchange=e=>{const select=e.target.checked;for(const row of scope){if(select&&!chosen.has(row.uuid))chosen.set(row.uuid,{...row,sample_required:false});else if(!select)chosen.delete(row.uuid);}draw();summary();};header();$('v261-page').textContent=`${page} / ${Math.max(1,Math.ceil(total/20))} 页 · 当前筛选 ${total} 捆`;$('v261-prev').disabled=page<=1;$('v261-next').disabled=page*20>=total;};
 const load=async()=>{const seq=++sequence;if(!$('v261-plan').value){rows=[];scope=[];total=0;draw();return;}try{const params={plan_id:$('v261-plan').value,search:$('v261-search').value};const [r,all]=await Promise.all([API.request('/v261/candidates?'+new URLSearchParams({...params,page})),API.request('/v261/candidates?'+new URLSearchParams({...params,all:true}))]);if(seq!==sequence)return;rows=r.items;scope=all.items;total=r.total;$('v261-error').textContent=total>500?'当前筛选超过500捆，请缩小编号筛选后使用全选。':'';draw();summary();}catch(e){if(seq===sequence)$('v261-error').textContent=e.message;}};
 $('v261-plan').onchange=()=>{chosen.clear();page=1;const p=plans.find(p=>p.id===$('v261-plan').value);$('v261-plan-info').textContent=p?`客户：${p.customer_name} · 合同：${p.contract_no||'未关联'} · 计划净重 ${Tonnes.format(p.target_weight)} t`:'';const locations=m.locations.filter(l=>l.map_usage==='FORMAL'&&l.active&&l.project_id===p?.project_id&&map.cells.some(c=>c.code===(l.map_cell_code||l.code)));$('v261-planned').innerHTML='<option value="">请选择统一规划货位</option>'+locations.map(l=>`<option value="${l.id}" ${['AVAILABLE','RELEASED'].includes(availability.items.find(x=>x.id===l.id)?.allocation_state)?'':'disabled'}>${esc(l.code)} · ${esc(V262.locationNames[availability.items.find(x=>x.id===l.id)?.allocation_state]||'不可用')} ${esc(availability.items.find(x=>x.id===l.id)?.lot_no||'')}</option>`).join('');summary();load();};$('v261-search-btn').onclick=()=>{page=1;load();};$('v261-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();page=1;load();}};$('v261-prev').onclick=()=>{page--;load();};$('v261-next').onclick=()=>{page++;load();};$('v261-clear').onclick=()=>{chosen.clear();draw();summary();};
 $('v261-create').onsubmit=e=>{e.preventDefault();if(!chosen.size){$('v261-error').textContent='请选择捆包';return;}$('v261-lot-dialog').showModal();};$('v261-modal-cancel').onclick=()=>$('v261-lot-dialog').close();$('v261-lot-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const a=await API.request('/v261/lots',{method:'POST',body:{plan_id:$('v261-plan').value,planned_location_id:$('v261-planned').value,lot_no:$('v261-lot-no').value,items:[...chosen.values()].map(r=>({bundle_id:r.uuid,sample_required:!!r.sample_required}))}});$('v261-lot-dialog').close();await Business.allocationDetail(a.id);}catch(err){$('v261-modal-error').textContent=err.message;e.submitter.disabled=false;}};draw();summary();
 },
 async detail(id){const a=await API.request('/v261/lots/'+id);if(a.workflow_version!=='2.6.1'){Business.open('历史备货档案 · '+(a.lot_no||a.code),`<p>历史单据按原版本保留，当前状态 ${esc(a.workflow_state||a.status)}；不自动迁移或重建历史锁定。</p>${V26.table(a.items)}<a href="/preparation/history-sampling">查询历史取样记录</a>${await V26.reviews('allocations',id)}`);return;}
 const editable=Business.can('allocation:write')&&['WORKING','RECTIFY'].includes(a.workflow_state),s=a.summary;
 Business.open('备货Lot · '+a.lot_no,`<p>客户 <strong>${esc(a.plan.customer_name)}</strong> · 销售计划 ${esc(a.plan.code)} · 合同 ${esc(a.plan.contract_no||'未关联')}<br>状态 <strong>${esc(this.states[a.workflow_state])}</strong> · 规划堆存货位 <strong>${esc(a.planned.code)}</strong>${['PREPARED','PARTIAL','FULFILLED'].includes(a.workflow_state)?'（主管已确认归位）':'（规划，不表示已实际归位）'}<br>审核 ${esc(a.reviewer_name||'待审核')} · ${esc(a.reviewed_at||'')} · ${esc(a.review_note||'')}</p><div class="v261-summary"><p>总捆数 ${s.total} · 取样 ${s.samples} · 取样中 ${s.sampling} · 已返回待检斤 ${s.returned}</p><p>已检斤 <strong>${s.weighed}</strong> · 待检斤 <strong>${s.unweighed}</strong> · 完成比例 ${s.total?Math.floor(s.weighed*100/s.total):0}%</p><p>${s.weighed===s.total?'完整Lot重量':'已检斤部分重量，尚非完整Lot总重'}：毛重 ${esc(s.known_gross)} t · 净重 ${esc(s.known_net)} t</p></div><label>明细筛选<select id="v261-filter"><option value="all">全部捆包</option><option value="sample">取样捆包</option><option value="non-sample">非取样捆包</option><option value="unweighed">未完成检斤</option></select></label><div id="v261-detail-items"></div><p>重量逐捆保存后生效；取样中不能最终检斤，返回必须已重新打包。已检斤后再次取样会作废本Lot最终重量并要求重新检斤，原重量修订记录保留。</p><label>审核 / 取消 / 作业说明<textarea id="v261-note" maxlength="1000"></textarea></label><p id="v261-detail-error" class="error" role="alert"></p><div class="business-toolbar">${editable?'<button id="v261-submit" class="button primary">提交备货审核</button>':''}${editable&&Business.can('lot:cancel-approve')&&![a.created_by,a.submitted_by].includes(CurrentUser.id)?'<button id="v261-cancel" class="button secondary">取消Lot审批</button>':''}${a.workflow_state==='PENDING'&&Business.can('allocation:review')&&![a.created_by,a.submitted_by].includes(CurrentUser.id)?'<label><input id="v261-stored" type="checkbox">确认全部捆包已完成检斤并归位</label><button id="v261-approve" class="button primary">主管审核通过</button><button id="v261-reject" class="button secondary">驳回待整改（保留锁定）</button>':''}</div>${a.workflow_state==='PREPARED'&&Business.can('allocation:review')&&![a.created_by,a.submitted_by].includes(CurrentUser.id)?'<button id="v261-reopen" class="button secondary">授权更正（保留锁定，未装车）</button>':''}<a href="/stock-map">查看实物与规划地图</a><h3>作业记录（最近500条，历史不覆盖）</h3><ol>${a.history.map(h=>`<li><strong>${esc(h.bundle_no||a.lot_no)}</strong> · ${esc(this.actionNames[h.action]||h.action)} · ${esc(h.actor_name)} · ${esc(h.occurred_at)} · ${esc(h.note||'')}<details><summary>变更前后</summary><pre>${esc('操作前：'+this.historySummary(h.before_data)+'\n操作后：'+this.historySummary(h.after_data))}</pre></details></li>`).join('')}</ol><dialog id="v261-cancel-dialog"><form id="v261-cancel-form" class="user-form"><h2>取消Lot并释放规划及锁定</h2><p>不删除已发生的取样或检斤历史。实验室取样中的捆包必须先返回。</p><label>取消原因<textarea id="v261-cancel-note" required maxlength="1000"></textarea></label><label><input id="v261-state-verified" type="checkbox">已核实全部捆包当前真实状态及所在位置</label><label>当前状态观察说明<textarea id="v261-observation" maxlength="1000"></textarea></label><p id="v261-cancel-error" class="error"></p><button id="v261-close-cancel" type="button">返回作业</button><button class="button primary">确认取消</button></form></dialog>`);
 const post=async(path,body,button)=>{if(button)button.disabled=true;try{await API.request(path,{method:'POST',body:{version:a.version,...body}});await Business.allocationDetail(id);}catch(e){$('v261-detail-error').textContent=e.message;if(button)button.disabled=false;}};
 const draw=()=>{const f=$('v261-filter').value,rows=a.items.filter(b=>f==='all'||f==='sample'&&b.sample_required||f==='non-sample'&&!b.sample_required||f==='unweighed'&&!b.final_weighed);$('v261-detail-items').innerHTML='<div class="business-table"><table><thead><tr><th>捆包 / 批次</th><th>当前确认货位</th><th>取样标记</th><th>取样进度</th><th>毛重(t)</th><th>净重(t)</th><th>作业</th></tr></thead><tbody>'+rows.map(b=>{const key=id+':'+b.id,draft=this.drafts.get(key),value=draft??(b.final_weighed?V26.weight(b.gross_weight):''),canWeigh=editable&&(!b.sample_required||['RETURNED','WEIGHED'].includes(b.sample_stage));return `<tr><td>${esc(b.bundle_no)}<br>${esc(b.batch)}</td><td>${esc(b.actual_location)}</td><td><input type="checkbox" data-v261-mark="${b.id}" aria-label="取样标记 ${esc(b.bundle_no)}" ${b.sample_required?'checked':''} ${editable&&['NOT_REQUIRED','WAITING'].includes(b.sample_stage)?'':'disabled'}></td><td>${esc(this.sampleStates[b.sample_stage])}</td><td>${canWeigh?`<input data-v261-gross="${b.id}" aria-label="毛重 ${esc(b.bundle_no)}" inputmode="decimal" value="${esc(value)}" placeholder="待检斤">`:b.final_weighed?V26.weight(b.gross_weight):'待检斤'}</td><td><output data-v261-net="${b.id}">${b.final_weighed?V26.weight(b.net_weight):'待检斤'}</output></td><td>${canWeigh?`<button type="button" data-v261-save="${b.id}">保存检斤</button>`:''}${editable&&b.sample_required&&['WAITING','WEIGHED'].includes(b.sample_stage)?`<button type="button" data-v261-stage="${b.id}" data-stage="IN_PROGRESS">${b.sample_stage==='WEIGHED'?'再次取样/重新检斤':'开始取样'}</button>`:''}${editable&&b.sample_stage==='IN_PROGRESS'?`<label><input type="checkbox" data-v261-repacked="${b.id}">已返回并重新打包</label><button type="button" data-v261-stage="${b.id}" data-stage="RETURNED">登记返回</button>`:''}</td></tr>`;}).join('')+'</tbody></table></div>';
 for(const cb of document.querySelectorAll('[data-v261-mark]'))cb.onchange=()=>post('/v261/lots/'+id+'/items/'+cb.dataset.v261Mark+'/sample-mark',{required:cb.checked},cb);
 for(const input of document.querySelectorAll('[data-v261-gross]'))input.oninput=()=>{this.drafts.set(id+':'+input.dataset.v261Gross,input.value);const out=document.querySelector('[data-v261-net="'+input.dataset.v261Gross+'"]');try{const g=V26.units(input.value);out.textContent=g>25n?V26.fixed(g-25n):'净重须大于0';}catch{out.textContent='待输入有效毛重';}};
 for(const b of document.querySelectorAll('[data-v261-save]'))b.onclick=()=>{const input=document.querySelector('[data-v261-gross="'+b.dataset.v261Save+'"]');const gross=input.value;this.drafts.delete(id+':'+b.dataset.v261Save);post('/v261/lots/'+id+'/items/'+b.dataset.v261Save+'/weigh',{gross_weight:gross,note:$('v261-note').value},b);};
 for(const b of document.querySelectorAll('[data-v261-stage]'))b.onclick=()=>post('/v261/lots/'+id+'/items/'+b.dataset.v261Stage+'/sample-stage',{stage:b.dataset.stage,repacked:!!document.querySelector('[data-v261-repacked="'+b.dataset.v261Stage+'"]')?.checked,note:$('v261-note').value},b);
 };$('v261-filter').onchange=draw;draw();for(const action of ['submit','approve','reject','reopen'])if($('v261-'+action))$('v261-'+action).onclick=e=>post('/v261/lots/'+id+'/'+action,{note:$('v261-note').value,all_weighed_and_stored:!!$('v261-stored')?.checked},e.target);
 if($('v261-cancel'))$('v261-cancel').onclick=()=>$('v261-cancel-dialog').showModal();$('v261-close-cancel').onclick=()=>$('v261-cancel-dialog').close();$('v261-cancel-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await API.request('/v261/lots/'+id+'/cancel',{method:'POST',body:{version:a.version,note:$('v261-cancel-note').value,current_state_verified:$('v261-state-verified').checked,observation:$('v261-observation').value}});$('v261-cancel-dialog').close();await Business.allocationDetail(id);}catch(err){$('v261-cancel-error').textContent=err.message;e.submitter.disabled=false;}};
 },
 async samplingHistory(id){if(id){const r=await API.request('/samples/'+id);Business.open('历史取样档案 · '+r.code,`<p>原取样记录保留，只读查询。${esc(r.status)} · ${esc(r.sample_date)} · ${esc(r.agency)}</p><p>${esc(r.result||'无历史结果')}</p>${V26.table(r.items)}<a href="/preparation/history-sampling">返回历史取样</a>`);return;}const r=await API.request('/samples');Business.open('备货管理 · 历史取样',`<p>本页保留原取样档案；新取样作业请进入所属Lot，不另建取样单。</p><a class="button primary" href="/preparation">返回备货Lot</a><div class="business-table"><table><thead><tr><th>原取样单</th><th>日期</th><th>机构</th><th>状态</th><th></th></tr></thead><tbody>${r.items.map(s=>`<tr><td>${esc(s.code)}</td><td>${esc(s.sample_date)}</td><td>${esc(s.agency)}</td><td>${esc(s.status)}</td><td><a href="/preparation/history-sampling/${s.id}">历史详情</a></td></tr>`).join('')}</tbody></table></div>`);}
};
Business.allocations=V261.allocations.bind(V261);Business.allocationEditor=V261.create.bind(V261);Business.allocationDetail=V261.detail.bind(V261);Flow.samples=()=>Router.go('/preparation/history-sampling');Flow.sample=id=>Router.go('/preparation/history-sampling/'+id);Flow.sampleForm=()=>Business.allocations();
const v261MapOpen=StockMap.open.bind(StockMap),v261MapDraw=StockMap.draw.bind(StockMap);
StockMap.draw=function(){v261MapDraw();for(const p of this.data.planning||[]){const l=this.data.locations.find(l=>l.id===p.planned_location_id);if(!l?.cell_code)continue;const cell=document.querySelector('[data-map-cell="'+l.cell_code+'"]');if(cell){cell.classList.add('map-planned');const title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent='规划/备货中：'+p.lot_no+' · '+p.customer+' · '+p.bundles+'捆，尚未确认为实际归位';cell.append(title);}}};
StockMap.open=async function(){await v261MapOpen();if(!$('stock-map-unmapped'))return;const section=document.createElement('section');section.id='v261-map-planning';section.innerHTML='<h3>规划堆存占用 / 备货中</h3><p>以下为Lot规划，实物仍按当前确认位置计数。虚线图格仅提示规划，不增加该格实物数量。</p><div class="business-table"><table><thead><tr><th>规划货位</th><th>Lot</th><th>客户</th><th>规划捆数</th><th>已检斤</th><th>已检斤净重(t)</th></tr></thead><tbody>'+(this.data.planning||[]).map(p=>'<tr><td>'+esc(p.planned_location)+'</td><td><a href="/preparation/'+p.id+'">'+esc(p.lot_no)+'</a></td><td>'+esc(p.customer)+'</td><td>'+p.bundles+'</td><td>'+p.weighed+'</td><td>'+Tonnes.format(p.known_net)+'</td></tr>').join('')+'</tbody></table></div>';$('stock-map-unmapped').before(section);};
const v261ScanOpen=Scan.open.bind(Scan);Scan.open=async function(){await v261ScanOpen();if($('scan-sample')){$('scan-sample').textContent='进入备货Lot登记取样';$('scan-sample').onclick=()=>{this.stop();Business.allocations();};}};
